export type secureConnectionsLogicType = MakeLogicType<secureConnectionsLogicValues, secureConnectionsLogicActions>

export const secureConnectionsLogic = kea<secureConnectionsLogicType>([
    path(['products', 'secureConnections', 'secureConnectionsLogic']),
    loaders(() => ({
        cdpApprovals: [
            { cdp_approved_connections: {} } as SecureConnectionApprovalsApi,
            {
                loadCdpApprovals: async () => secureConnectionsCdpApprovalsRetrieve(String(getCurrentTeamId())),
                setCdpApproval: async ({ connectionId, approved }) =>
                    secureConnectionsCdpApprovalsCreate(String(getCurrentTeamId()), {
                        connection_id: connectionId,
                        approved,
                    }),
            },
        ],
        connectionStatus: [
            null as SecureConnectionStatusApi | null,
            {
                loadConnectionStatus: async () => secureConnectionsRetrieve(String(getCurrentTeamId())),
            },
        ],
        enrollment: [
            null as SecureConnectionEnrollmentApi | null,
            {
                createEnrollment: async () => secureConnectionsCreate(String(getCurrentTeamId())),
            },
        ],
        testResult: [
            null as SecureConnectionTestApi | null,
            {
                testConnection: async () => secureConnectionsTestRetrieve(String(getCurrentTeamId())),
            },
        ],
    })),
    afterMount(({ actions }) => {
        actions.loadConnectionStatus()
        actions.loadCdpApprovals()
    }),
])
